"""一次性离线核验 v66；不构建、不重跑 LP。"""
import collections, copy, datetime, gzip, hashlib, json, math, re, statistics, subprocess, sys, zipfile
from pathlib import Path
sys.dont_write_bytecode = True
ROOT = Path(__file__).resolve().parents[1]
DATA = ROOT / "knowledge/experiments/data/2026-10-12-halpern-ipm"
PLAN_SHA = "5f134f630f8f969097c2b9c2b85912a89b4f20ef224043303367d43754d1dd06"
ABSENT_FIELDS = ("ipm_extended_krylov_attempts", "ipm_extended_krylov_successes",
                 "ipm_homogeneous_scalar_checks", "ipm_homogeneous_scalar_rejections")
COUNT_FIELDS = ('ipm_iterations', 'ipm_factorizations', 'ipm_refinement_steps', 'ipm_weighted_krylov_steps', 'ipm_krylov_recycle_projections', 'ipm_krylov_recycle_acceptances', 'ipm_krylov_recycle_vectors', 'ipm_krylov_recycle_peak_dimension', 'ipm_regularization_searches', 'ipm_regularization_reductions', 'ipm_unshifted_factorizations', 'ipm_full_newton_preconditioner_solves', 'ipm_full_newton_products', 'ipm_bounded_newton_returns', 'ipm_bounded_newton_inexact_returns', 'ipm_homogeneous_constant_solves', 'ipm_homogeneous_constant_repairs', 'ipm_homogeneous_constant_repair_successes', 'ipm_homogeneous_direction_solves', 'ipm_homogeneous_scaled_products', 'ipm_homogeneous_scaled_refinement_steps', 'ipm_homogeneous_scaled_inexact_returns', 'ipm_direction_retries', 'ipm_direction_retry_successes', 'ipm_schur_residual_products', 'ipm_schur_refinement_steps', 'ipm_schur_refinement_acceptances', 'ipm_kkt_dimension', 'ipm_factor_nonzeros', 'ipm_structural_fallbacks', 'ipm_eliminated_singletons', 'ipm_regularized_pivots', 'ipm_backward_error_acceptances', 'ipm_inexact_acceptances', 'ipm_inexact_prefilter_rejections', 'ipm_eliminated_fixed_variables', 'ipm_presolved_singleton_rows', 'ipm_presolved_fixed_columns', 'ipm_central_correction_attempts', 'ipm_central_correction_acceptances')
NULLABLE_COUNTS = {"ipm_kkt_dimension", "ipm_factor_nonzeros", "ipm_eliminated_singletons"}
COMPAT = ("compatibility-development", "compatibility-probe")
STAGES = (*COMPAT, "development", "probe", "netlib", "highs")
ALLOWED = {"optimal": (0, "resolved"), "empty": (0, "resolved"), "infeasible": (0, "resolved"),
    "unbounded": (0, "resolved"), "verification_failed": (3, "verification_failed"),
    "time_limit": (4, "incomplete"), "iteration_limit": (4, "incomplete"), "numerical_error": (4, "incomplete")}

def require(condition, message):
    if not condition:
        raise AssertionError(message)

def strict(text):
    def pairs(values):
        result = {}
        for key, value in values:
            require(key not in result, "JSON 重复键")
            result[key] = value
        return result
    def number(text):
        value = float(text)
        require(math.isfinite(value), "JSON 非有限浮点")
        return value
    def invalid(text):
        raise ValueError("JSON 非有限常量：" + text)
    return json.loads(text, object_pairs_hook=pairs, parse_float=number, parse_constant=invalid)

def read(path):
    return strict(Path(path).read_text(encoding="utf-8"))

def sha(path):
    digest = hashlib.sha256()
    with Path(path).open("rb") as source:
        for chunk in iter(lambda: source.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()

def finite(value):
    return type(value) in (int, float) and math.isfinite(value)

def same(a, b):
    if type(a) is bool or type(b) is bool:
        return type(a) is type(b) and a == b
    if isinstance(a, dict) and isinstance(b, dict):
        return a.keys() == b.keys() and all(same(a[key], b[key]) for key in a)
    if isinstance(a, list) and isinstance(b, list):
        return len(a) == len(b) and all(same(x, y) for x, y in zip(a, b))
    return a == b

def flags(arguments):
    require(len(arguments) % 2 == 0, "参数必须成对")
    result = dict(zip(arguments[::2], arguments[1::2]))
    require(len(result) * 2 == len(arguments) and all(key.startswith("--") for key in result), "重复或非法参数")
    return result

def valid_counts(report, version, backend, mode):
    if not isinstance(report, dict) or set(COUNT_FIELDS) - report.keys() or set(ABSENT_FIELDS) & report.keys():
        return False
    values = {key: report[key] for key in COUNT_FIELDS}
    if backend != "ipm":
        return all(value is None for value in values.values())
    for key, value in values.items():
        if value is None and key in NULLABLE_COUNTS:
            continue
        if type(value) is not int or value not in range(0, 1 << 63):
            return False
    weight = values["ipm_weighted_krylov_steps"]
    if weight > values["ipm_refinement_steps"] or mode == "homogeneous_repair" and weight != 0:
        return False
    work = [values["ipm_homogeneous_constant_" + tail] for tail in ("repair_successes", "repairs", "solves")]
    return work == sorted(work)


def factor_path_valid(report, backend):
    if "ipm_factor_backend" not in report:
        return False
    actual = report["ipm_factor_backend"]
    if backend == "highs":
        return actual is None
    options = report.get("options")
    ipm = options.get("ipm") if isinstance(options, dict) else None
    wanted = ipm.get("linear_solver") if isinstance(ipm, dict) else None
    if wanted not in {"normal_cholmod", "normal_cholmod_aat"}:
        return False
    if actual is None:
        return True
    fallback = report.get("ipm_structural_fallbacks")
    if actual == "factorhighs":
        return type(fallback) is int and fallback >= 1
    return actual == wanted and type(fallback) is int and fallback == 0

def valid_process(row):
    report = row.get("report")
    if row.get("error") is not None or not isinstance(report, dict) or type(row.get("returncode")) is not int:
        return False
    if type(report.get("schema_version")) is not int or report["schema_version"] != 1:
        return False
    status = report.get("status")
    if not isinstance(status, str) or status not in ALLOWED or row.get("status") != status:
        return False
    if (row["returncode"], row.get("classification")) != ALLOWED[status]:
        return False
    times = report.get("timings")
    if not isinstance(times, dict) or not all(finite(times.get(key)) and times[key] >= 0 for key in ("read_seconds", "solve_seconds", "verification_seconds", "total_seconds")):
        return False
    backend, options = report.get("backend"), report.get("options")
    if backend not in ("ipm", "highs") or not isinstance(options, dict):
        return False
    ipm = options.get("ipm")
    mode = ipm.get("linear_accuracy") if isinstance(ipm, dict) else None
    if backend == "ipm" and not isinstance(mode, str) or not valid_counts(report, None, backend, mode) or not factor_path_valid(report, backend):
        return False
    return finite(row.get("elapsed_wall_seconds")) and row["elapsed_wall_seconds"] > 0 and finite(row.get("numerical_seconds")) and row["numerical_seconds"] >= 0

def limited(row):
    return row.get("error") == "wall_timeout" or (row.get("report") or {}).get("status") == "time_limit" or (finite(row.get("elapsed_wall_seconds")) and row["elapsed_wall_seconds"] > 35) or (finite(row.get("numerical_seconds")) and row["numerical_seconds"] > 5)

def trajectory(a, b):
    reports = copy.deepcopy([a.get("report"), b.get("report")])
    for report in reports:
        if isinstance(report, dict):
            for key in ("timings", "backend_version"):
                report.pop(key, None)
    equal = same(*reports) and a.get("returncode") == b.get("returncode") and a.get("error") == b.get("error")
    valid, budget = valid_process(a) and valid_process(b), limited(a) or limited(b)
    return {"equal": equal, "valid_processes": valid, "budget_limited": budget,
        "category": "invalid_process" if not valid else "budget_limited" if budget else "equal" if equal else "different"}

def self_check():
    base = dict.fromkeys(COUNT_FIELDS, 0)
    row = {"error": None, "returncode": 4, "classification": "incomplete", "status": "numerical_error",
        "numerical_seconds": 1, "elapsed_wall_seconds": 2,
        "report": {"schema_version": 1, "status": "numerical_error", "backend": "ipm",
            "backend_version": "ipm-cpu-0.47.0", "ipm_factor_backend": None, **base,
            "options": {"ipm": {"linear_accuracy": "homogeneous_repair", "linear_solver": "normal_cholmod"}},
            "timings": {"read_seconds": 0, "solve_seconds": 1, "verification_seconds": 0, "total_seconds": 1}}}
    budget = copy.deepcopy(row); budget["status"] = budget["report"]["status"] = "time_limit"
    modern = copy.deepcopy(row); modern["report"]["backend_version"] = "ipm-cpu-0.53.0"
    require(trajectory(row,modern)["category"] == "equal", "版本差异允许")
    require(trajectory(row,budget)["category"] == "budget_limited", "有效预算分叉")
    changed = copy.deepcopy(row); changed["report"]["message"] = "不同轨迹"
    require(trajectory(row,changed)["category"] == "different", "不得屏蔽非时间轨迹")
    changed = copy.deepcopy(row); changed["report"]["options"]["ipm"]["linear_solver"] = "normal_cholmod_aat"
    require(trajectory(row,changed)["category"] == "different", "不得屏蔽线性求解器")
    count_cases = []
    for key in COUNT_FIELDS:
        for value in (True, False, -1, 0.5, 1 << 63, "0", []):
            item = dict(base); item[key] = value
            count_cases.append((item,False))
        item = dict(base); item.pop(key); count_cases.append((item,False))
        item = dict(base); item[key] = None; count_cases.append((item,key in NULLABLE_COUNTS))
    for key in ABSENT_FIELDS:
        item = dict(base); item[key] = None; count_cases.append((item,False))
    count_cases.append((base,True))
    for field, value in (("ipm_homogeneous_constant_repairs", 1), ("ipm_homogeneous_constant_repair_successes", 1),
                         ("ipm_weighted_krylov_steps", 1)):
        item = dict(base); item[field] = value; count_cases.append((item,False))
    item = dict(base); item.update(ipm_homogeneous_constant_repairs=2,ipm_homogeneous_constant_repair_successes=1,
        ipm_homogeneous_constant_solves=3,ipm_refinement_steps=8); count_cases.append((item,True))
    for item, expected in count_cases:
        require(valid_counts(item,66,"ipm","homogeneous_repair") is expected,"独立完整计数反例")
    nulls = dict.fromkeys(COUNT_FIELDS,None)
    require(valid_counts(nulls,66,"highs",None) and not valid_counts(base,66,"highs",None),"非IPM统计必须null")
    status_cases = 0
    for status, (code, classification) in ALLOWED.items():
        for item, expected in count_cases:
            if expected: continue
            bad = copy.deepcopy(row); bad.update(status=status,returncode=code,classification=classification)
            bad["report"]["status"] = status
            for key in COUNT_FIELDS: bad["report"].pop(key)
            bad["report"].update(item)
            require(not valid_process(bad) and trajectory(bad,budget)["category"] == "invalid_process",
                "全部状态非法计数优先预算")
            status_cases += 1
    process_cases = 0
    for key, value in (("returncode", True),("returncode",0),("returncode",-1073741819),("error","wall_timeout"),
        ("error","launch_error"),("numerical_seconds",float("nan")),("numerical_seconds",None),("elapsed_wall_seconds",0)):
        bad=copy.deepcopy(row);bad[key]=value
        require(trajectory(bad,budget)["category"]=="invalid_process","非法进程优先预算"); process_cases+=1
    path_cases = 0
    for requested in ("normal_cholmod", "normal_cholmod_aat"):
        for actual, count, expected in ((None,0,True),(None,1,True),(requested,0,True),(requested,1,False),
            ("factorhighs",1,True),("factorhighs",0,False),("qdldl",0,False)):
            item=copy.deepcopy(row["report"]); item["options"]["ipm"]["linear_solver"]=requested
            item.update(ipm_factor_backend=actual,ipm_structural_fallbacks=count)
            require(factor_path_valid(item,"ipm") is expected,"实际后端与结构回退标签"); path_cases+=1
    try: strict('{"x":1,"x":2}')
    except AssertionError: pass
    else: raise AssertionError("重复JSON键未拒绝")
    require(not same({"x":True},{"x":1}),"布尔不等于整数")
    return {"passed":True,"count_cases":len(count_cases)+2,"all_status_invalid_budget_cases":status_cases,
        "trajectory_cases":4,"process_cases":process_cases,"factor_path_cases":path_cases,"json_type_cases":2,"lp_runs":0}

def expected_options(backend, mode, linear):
    return {"backend": backend, "time_limit": 5, "threads": 1, "seed": 0, "mip_relative_gap": 0.0001, "pdlp": None,
        "ipm": None if backend == "highs" else {"method": "homogeneous", "max_iterations": 200, "scaling_passes": 5, "objective_scaling": False, "eliminate_singletons": True, "dynamic_regularization": False, "equilibrate_kkt": True, "linear_accuracy": mode, "central_corrections": 0, "direction_retries": 0, "krylov_history_size": 0, "linear_solver": linear, "eliminate_fixed_variables": True, "presolve_singleton_rows": False, "eliminate_presolved_fixed_variables": False, "inexact_prefilter": False},
        "highs": {"solver": "choose", "run_crossover": "on", "presolve": "choose"} if backend == "highs" else None,
