def numerical_flags(backend, mode, linear):
    result = {"--backend": backend, "--time-limit": "5.0", "--threads": "1", "--seed": "0", "--mip-gap": "0.0001"}
    if backend == "highs":
        result.update({"--highs-solver": "choose", "--highs-crossover": "on", "--highs-presolve": "choose"})
    else:
        result.update({"--iteration-limit": "200", "--scaling-passes": "5", "--ipm-method": "homogeneous", "--ipm-linear-accuracy": mode, "--ipm-linear-solver": linear, "--ipm-direction-retries": "0", "--ipm-objective-scaling": "off", "--ipm-singleton-elimination": "on", "--ipm-dynamic-regularization": "off", "--ipm-kkt-equilibration": "on", "--ipm-fixed-variable-elimination": "on", "--ipm-singleton-presolve": "off", "--ipm-presolve-fixed-elimination": "off", "--ipm-krylov-history-size": "0", "--ipm-central-corrections": "0", "--ipm-inexact-prefilter": "off"})
    return result

def sgm(values):
    return math.expm1(sum(math.log1p(value / 10.0) for value in values) / len(values)) * 10.0

def audit_summary(summary, rows, models, repeats, sides):
    require(summary["model_count"] == len(models) and summary["repeats"] == repeats and summary["run_count"] == len(rows), "汇总数量")
    require(summary["quality_pass_count"] == sum(row["quality_pass"] for row in rows), "总达标数")
    result = {}
    for side in sides:
        selected = [row for row in rows if row["requested_variant"] == side]
        counts = collections.Counter(row["model_index"] for row in selected if row["quality_pass"])
        expected = {"run_count": len(selected), "quality_pass_count": sum(row["quality_pass"] for row in selected),
            "all_repeats_quality_pass_model_count": sum(counts[model["model_index"]] == repeats for model in models),
            "quality_failure_counts": dict(collections.Counter(row["quality_failure"] for row in selected if not row["quality_pass"])),
            "status_counts": dict(collections.Counter(row["status"] for row in selected)),
            "penalized_wall_sgm10_seconds": sgm([row["quality_penalized_wall_seconds"] for row in selected]),
            "penalized_numerical_sgm10_seconds": sgm([row["quality_penalized_numerical_seconds"] for row in selected]),
            "numerical_budget_exceeded_count": sum(row["numerical_budget_exceeded"] for row in selected),
            "wall_budget_exceeded_count": sum(row["wall_budget_exceeded"] for row in selected)}
        require(same(summary["variants"][side], expected), "独立重算每侧 SGM/覆盖/状态")
        result[side] = expected
    require(len(summary["models"]) == len(models), "逐例汇总数量")
    both, winners = 0, collections.Counter()
    for model, item in zip(models, summary["models"]):
        groups = {side: [row for row in rows if row["requested_variant"] == side and row["model_index"] == model["model_index"]] for side in sides}
        require(all(len(group) == repeats for group in groups.values()), "逐例重复次数")
        counts = {side: sum(row["quality_pass"] for row in group) for side, group in groups.items()}
        require((item["input"], item["sha256"], item["model_index"]) == (model["input"], model["sha256"], model["model_index"]), "逐例身份")
        require(item["quality_pass_counts"] == counts, "逐例达标次数")
        complete = all(value == repeats for value in counts.values())
        require(item["all_repeats_quality_pass"] is complete, "双方完整达标标志")
        if complete:
            both += 1
            for kind, field in (("wall", "elapsed_wall_seconds"), ("numerical", "numerical_seconds")):
                median = {side: statistics.median(row[field] for row in group) for side, group in groups.items()}
                ranges = {side: [min(row[field] for row in group), max(row[field] for row in group)] for side, group in groups.items()}
                require(item["median_" + kind + "_seconds"] == median and item[kind + "_range_seconds"] == ranges, "逐例中位数/区间")
                ratio = median[sides[0]] / median[sides[1]] if median[sides[1]] > 0 else None
                require(item[kind + "_speedup_reference_over_candidate"] == ratio, "逐例速度比")
                if kind == "wall":
                    winner = "tie" if median[sides[0]] == median[sides[1]] else min(median, key=median.get)
                    require(item["wall_winner"] == winner, "逐例墙钟胜者")
                    winners[winner] += 1
        else:
            require(all(item[key] is None for key in ("median_wall_seconds", "median_numerical_seconds", "wall_range_seconds", "numerical_range_seconds", "wall_speedup_reference_over_candidate", "numerical_speedup_reference_over_candidate", "wall_winner")), "失败样本不得计算成功速度")
    require(summary["both_variants_all_repeats_pass_count"] == both and summary["wall_winner_counts"] == dict(winners), "整体成对统计")
    return result

def audit_wrapped_attempts(prefix, script, arguments):
    paths = sorted(DATA.glob(prefix + "-attempt[0-9]*.json"),
        key=lambda path: int(re.search(r"attempt([0-9]+)",path.name).group(1)))
    require(bool(paths) and [int(re.search(r"attempt([0-9]+)",p.name).group(1)) for p in paths] ==
        list(range(1,len(paths)+1)), "外层执行attempt完整连续：" + prefix)
    result = []; previous = datetime.datetime.fromisoformat(read(DATA/"v66-plan.json")["created_at_utc"])
    wrapper = ROOT/".tools/v66-attempt-inline.py"
    for path in paths:
        record = read(path)
        begin,end = (datetime.datetime.fromisoformat(record[key]) for key in ("started_at_utc","completed_at_utc"))
        require(begin >= previous and end >= begin and finite(record["elapsed_seconds"]) and record["elapsed_seconds"] >= 0,
            "真实调用前开始与调用后完成时刻")
        previous = end
        require(type(record["returncode"]) is int and record["command"] == [sys.executable,str(script),*arguments],
            "外层实际命令与退出码")
        require(hashlib.sha256(record["source"].encode("utf-8")).hexdigest() == record["source_sha256"] and
            hashlib.sha256(record["wrapper_source"].encode("utf-8")).hexdigest() == record["wrapper_sha256"] == sha(wrapper),
            "按原bytes保存脚本和wrapper，CRLF属于原身份")
        result.append({"attempt":path.name,"attempt_sha256":sha(path),"started_at_utc":record["started_at_utc"],
            "completed_at_utc":record["completed_at_utc"],"returncode":record["returncode"],
            "source_sha256":record["source_sha256"],"wrapper_sha256":record["wrapper_sha256"],
            "stdout":record["stdout"],"stderr":record["stderr"]})
    require(result[-1]["returncode"] == 0 and result[-1]["stderr"] == "" and
        result[-1]["source_sha256"] == sha(script), "最后一次成功执行对应当前已锁定脚本")
    return result


def audit_build_history(plan, current):
    paths = sorted(DATA.glob("v66-build-attempt[0-9]*.json"),
        key=lambda path: int(re.search(r"attempt([0-9]+)", path.name).group(1)))
    require(bool(paths), "至少保留一次实际构建记录")
    numbers = [int(re.search(r"attempt([0-9]+)", path.name).group(1)) for path in paths]
    require(numbers == list(range(1, len(paths)+1)), "构建尝试必须完整连续")
    attempts = [read(path) for path in paths]
    require(attempts[-1]["returncode"] == 0 and attempts[-1]["error"] is None, "最终冻结必须来自成功构建")
    plan_time = datetime.datetime.fromisoformat(plan["created_at_utc"])
    previous_time = plan_time
    history = []
    def resolve(value):
        path = Path(value)
        path = path if path.is_absolute() else DATA / path
        require(path.resolve().is_relative_to(ROOT) and path.is_file(), "构建证据必须真实保留在工作区")
        return path
    for number, path, attempt in zip(numbers, paths, attempts):
        require(attempt["plan_sha256"] == PLAN_SHA and attempt["baseline_check_sha256"] == plan["baseline_check"]["sha256"] and
            attempt["lp_runs"] == 0 and type(attempt["build_invocation_attempted"]) is bool, "构建驱动范围与计划")
        driver_start = datetime.datetime.fromisoformat(attempt["driver_started_at_utc"])
        ended = datetime.datetime.fromisoformat(attempt["completed_at_utc"])
        require(driver_start >= previous_time and ended >= driver_start, "构建驱动实际开始完成顺序")
        require(hashlib.sha256(attempt["driver_source"].encode("utf-8")).hexdigest() == attempt["driver_sha256"],
            "构建驱动原字节源码留存")
        if not attempt["build_invocation_attempted"]:
            require(number != len(paths) and attempt["returncode"] is None and attempt["started_at_utc"] is None and
                attempt["error"] is not None, "构建前预检失败单独保留，不能冒充实际测试")
            history.append({"attempt":path.name,"attempt_sha256":sha(path),"returncode":None,
                "precheck_failed":True,"started_at_utc":None,"completed_at_utc":attempt["completed_at_utc"]})
            previous_time = ended
            continue
        require(attempt["sources_unchanged"] is True and type(attempt["returncode"]) is int,
            "实际构建退出码与来源稳定性")
        require(attempt["anchor_file"] == "v66-integration.json" and
            attempt["anchor_sha256"] == sha(DATA/attempt["anchor_file"]) and
            attempt["starting_state_sha256"] == plan["starting_state"]["sha256"], "构建实际集成锚点")
        external = {name:value for name,value in current["libraries"].items() if not Path(name).name.startswith("libsolver_")}
        require(attempt["external_libraries_before_and_after"] == external, "每次构建8外部库不变")
        require(attempt["command"] == [r"C:\Users\ADMIN\.cache\codex-runtimes\codex-primary-runtime\dependencies\native\powershell\pwsh.exe",
            "-NoProfile", "-File", str(ROOT/"scripts/build-windows.ps1"), "-Jobs", "4"], "真实统一构建命令")
        when = datetime.datetime.fromisoformat(attempt["started_at_utc"])
        require(driver_start <= when <= ended and when >= previous_time, "先冻结计划，再依序构建")
        previous_time = ended
        require(set(attempt["source_sha256"]) == set(plan["changed_source_files"]), "每次构建11来源集合")
        require(set(attempt["all_sources_sha256"]) == set(current["files"]) and
            all(attempt["all_sources_sha256"][name] == value for name,value in attempt["source_sha256"].items()),
            "每次构建95来源全集与11项差集对应")
